// Package rtp parses framed RTP captures and reconstructs per-SSRC sequence
// state.
//
// A capture is a small self-describing container generated by this project:
//
//	"RTPJ"                      4-byte magic
//	repeated:
//	  length   uint32 big-endian  length of the following RTP datagram
//	  datagram bytes              one RTP packet, header + payload
//
// RTP itself carries no packet length, so the container supplies the framing
// that lets a truncated datagram be detected rather than silently merged into
// its successor. Parsing streams one datagram at a time and never retains
// payloads; memory is bounded by the largest datagram plus the coalesced
// received/gap intervals.
package rtp

import (
	"encoding/binary"
	"fmt"
	"io"
	"sort"

	pionrtp "github.com/pion/rtp"

	"media.rebuild/internal/model"
)

// Magic opens every capture produced or consumed by this kernel.
const Magic = "RTPJ"

// DefaultClockRate is the RTP timestamp rate used when a track does not
// declare one.
const DefaultClockRate = 90000

// DefaultMaxDatagram bounds a single datagram so a corrupt length field cannot
// force a huge allocation.
const DefaultMaxDatagram = 65535

// DefaultMaxRecords bounds retained per-packet records. Sequence statistics
// keep counting past the cap, so a long capture streams in bounded memory;
// only the retained record list is truncated.
const DefaultMaxRecords = 100_000

// Range is an inclusive interval of extended sequence numbers.
type Range struct {
	First uint64 `json:"first"`
	Last  uint64 `json:"last"`
}

// Record is one received RTP packet.
type Record struct {
	Offset      int64  `json:"offset"`
	SSRC        uint32 `json:"ssrc"`
	Sequence    uint16 `json:"sequence"`
	ExtSequence uint64 `json:"ext_sequence"`
	Timestamp   uint32 `json:"timestamp"`
	TimeNs      int64  `json:"time_ns"`
	Marker      bool   `json:"marker"`
	PayloadType uint8  `json:"payload_type"`
	PayloadLen  int    `json:"payload_len"`
	Duplicate   bool   `json:"duplicate"`
	Reordered   bool   `json:"reordered"`
	FirstOfSSRC bool   `json:"first_of_ssrc"`
}

// SSRCStats summarizes one synchronization source.
type SSRCStats struct {
	SSRC        uint32  `json:"ssrc"`
	Packets     int     `json:"packets"`
	Unique      int     `json:"unique"`
	Duplicates  int     `json:"duplicates"`
	Reordered   int     `json:"reordered"`
	Gaps        int     `json:"gaps"`
	Missing     uint64  `json:"missing"`
	GapRanges   []Range `json:"gap_ranges"`
	FirstPacket uint64  `json:"first_ext_seq"`
	LastPacket  uint64  `json:"last_ext_seq"`
}

// Capture is the parsed result for one input.
type Capture struct {
	Source    string         `json:"source"`
	ClockRate uint32         `json:"clock_rate"`
	Records   []*Record      `json:"records"`
	Errors    []*model.Error `json:"errors"`
	Streams   []SSRCStats    `json:"streams"`
	// RecordsTruncated counts packets received but not retained because the
	// record cap was reached.
	RecordsTruncated int64 `json:"records_truncated"`
}

// Totals returns aggregate duplicate and gap counts across all SSRCs.
func (c *Capture) Totals() (duplicates int, gaps int, missing uint64) {
	for _, s := range c.Streams {
		duplicates += s.Duplicates
		gaps += s.Gaps
		missing += s.Missing
	}
	return
}

// Options controls parsing.
type Options struct {
	ClockRate   uint32
	MaxDatagram int
	MaxRecords  int
}

func (o Options) normalized() Options {
	if o.ClockRate == 0 {
		o.ClockRate = DefaultClockRate
	}
	if o.MaxDatagram == 0 {
		o.MaxDatagram = DefaultMaxDatagram
	}
	if o.MaxRecords == 0 {
		o.MaxRecords = DefaultMaxRecords
	}
	return o
}

// seqSet maintains coalesced intervals of received extended sequence numbers.
type seqSet struct {
	ranges []Range
}

// add inserts n and reports whether it was already present.
func (s *seqSet) add(n uint64) bool {
	// Binary search for the first range whose Last >= n.
	i := sort.Search(len(s.ranges), func(i int) bool { return s.ranges[i].Last >= n })
	if i < len(s.ranges) && s.ranges[i].First <= n {
		return true // already received
	}
	// n sits strictly after range i-1's Last (or before range i's First when
	// i == len). It may touch either neighbour, so coalesce on both sides.
	touchPrev := i > 0 && s.ranges[i-1].Last+1 == n
	touchNext := i < len(s.ranges) && s.ranges[i].First == n+1
	switch {
	case touchPrev && touchNext:
		// Bridge the gap: extend the previous range and drop the next one.
		s.ranges[i-1].Last = s.ranges[i].Last
		s.ranges = append(s.ranges[:i], s.ranges[i+1:]...)
	case touchPrev:
		s.ranges[i-1].Last = n
	case touchNext:
		s.ranges[i].First = n
	default:
		s.ranges = append(s.ranges, Range{})
		copy(s.ranges[i+1:], s.ranges[i:])
		s.ranges[i] = Range{First: n, Last: n}
	}
	return false
}

// missing returns the total absent count and the gap ranges within
// [first,last]. Only ranges that intersect the window contribute.
func (s *seqSet) missing(first, last uint64) (uint64, []Range) {
	if len(s.ranges) == 0 || last < first {
		return 0, nil
	}
	var gaps []Range
	cursor := first
	for _, r := range s.ranges {
		if r.Last < first {
			continue
		}
		if r.First > last {
			break
		}
		if r.First > cursor {
			gaps = append(gaps, Range{First: cursor, Last: r.First - 1})
		}
		if r.Last >= cursor {
			cursor = r.Last + 1
		}
	}
	if cursor <= last {
		gaps = append(gaps, Range{First: cursor, Last: last})
	}
	var absent uint64
	for _, g := range gaps {
		absent += g.Last - g.First + 1
	}
	return absent, gaps
}

// ssrState is the per-SSRC sequence and timestamp reconstruction state.
type ssrState struct {
	ssrc     uint32
	lastSeq  uint16
	lastExt  uint64
	lastTS   uint32
	extTS    uint64
	firstExt uint64
	maxExt   uint64
	seen     seqSet
	stats    SSRCStats
}

// extendSeq maps a wire sequence number to an extended one that is monotonic
// across 16-bit wrap, using the RFC 3550 shortest-distance rule.
func (st *ssrState) extendSeq(seq uint16, initialized bool) uint64 {
	if !initialized {
		return uint64(seq)
	}
	delta := int32(int16(seq - st.lastSeq))
	return uint64(int64(st.lastExt) + int64(delta))
}

// extendTS maps a 32-bit RTP timestamp to a monotonic 64-bit value.
func (st *ssrState) extendTS(ts uint32, initialized bool) uint64 {
	if !initialized {
		return uint64(ts)
	}
	delta := int32(ts - st.lastTS)
	return uint64(int64(st.extTS) + int64(delta))
}

// Read parses a capture from r. Errors are collected; a truncated datagram or
// a corrupt frame ends parsing because the framing can no longer be trusted.
func Read(r io.Reader, source string, opts Options) (*Capture, error) {
	opts = opts.normalized()
	c := &Capture{Source: source, ClockRate: opts.ClockRate}
	var magic [4]byte
	n, err := io.ReadFull(r, magic[:])
	if err != nil {
		if err == io.EOF || err == io.ErrUnexpectedEOF {
			c.Errors = append(c.Errors, model.Newf(model.CodeRTPHeader, model.Source{Name: source, Offset: 0},
				"capture is shorter than the 4-byte magic (read %d bytes)", n))
			return c, nil
		}
		return nil, err
	}
	if string(magic[:]) != Magic {
		c.Errors = append(c.Errors, model.Newf(model.CodeRTPHeader, model.Source{Name: source, Offset: 0},
			"bad capture magic %q", magic[:]))
		return c, nil
	}

	offset := int64(4)
	states := make(map[uint32]*ssrState)
	var buf []byte
	for {
		var lenBuf [4]byte
		n, err := io.ReadFull(r, lenBuf[:])
		if err == io.EOF {
			break
		}
		if err == io.ErrUnexpectedEOF {
			c.Errors = append(c.Errors, model.Newf(model.CodeRTPTruncated, model.Source{Name: source, Offset: offset},
				"frame length truncated (%d of 4 bytes)", n))
			break
		}
		if err != nil {
			return nil, err
		}
		recOffset := offset
		plen := binary.BigEndian.Uint32(lenBuf[:])
		offset += 4
		if plen > uint32(opts.MaxDatagram) {
			c.Errors = append(c.Errors, model.Newf(model.CodeRTPHeader, model.Source{Name: source, Offset: recOffset},
				"datagram length %d exceeds limit %d", plen, opts.MaxDatagram))
			break
		}
		if uint32(cap(buf)) < plen {
			buf = make([]byte, plen)
		} else {
			buf = buf[:plen]
		}
		n, err = io.ReadFull(r, buf)
		if err == io.ErrUnexpectedEOF || err == io.EOF {
			c.Errors = append(c.Errors, model.Newf(model.CodeRTPTruncated, model.Source{Name: source, Offset: recOffset},
				"datagram truncated: declared %d bytes, got %d", plen, n))
			break
		}
		if err != nil {
			return nil, err
		}
		if plen < 12 {
			c.Errors = append(c.Errors, model.Newf(model.CodeRTPTruncated, model.Source{Name: source, Offset: recOffset},
				"datagram shorter than the 12-byte RTP header (%d bytes)", plen))
			offset += int64(plen)
			continue
		}
		var hdr pionrtp.Header
		hdrLen, err := hdr.Unmarshal(buf)
		if err != nil {
			c.Errors = append(c.Errors, model.New(model.CodeRTPHeader, model.Source{Name: source, Offset: recOffset},
				"malformed RTP header", err))
			offset += int64(plen)
			continue
		}
		if hdr.Version != 2 {
			c.Errors = append(c.Errors, model.Newf(model.CodeRTPHeader, model.Source{Name: source, Offset: recOffset},
				"unsupported RTP version %d", hdr.Version))
			offset += int64(plen)
			continue
		}
		padLen := 0
		if hdr.Padding {
			padLen = int(buf[len(buf)-1])
			if padLen == 0 || hdrLen+padLen > len(buf) {
				c.Errors = append(c.Errors, model.Newf(model.CodeRTPTruncated, model.Source{Name: source, Offset: recOffset},
					"padding length %d does not fit datagram of %d bytes", padLen, len(buf)))
				offset += int64(plen)
				continue
			}
		}

		st, ok := states[hdr.SSRC]
		if !ok {
			st = &ssrState{ssrc: hdr.SSRC}
			states[hdr.SSRC] = st
		}
		rec := &Record{
			Offset:      recOffset,
			SSRC:        hdr.SSRC,
			Sequence:    hdr.SequenceNumber,
			Timestamp:   hdr.Timestamp,
			Marker:      hdr.Marker,
			PayloadType: hdr.PayloadType,
			PayloadLen:  len(buf) - hdrLen - padLen,
			FirstOfSSRC: !ok,
		}
		rec.ExtSequence = st.extendSeq(hdr.SequenceNumber, ok)
		extTS := st.extendTS(hdr.Timestamp, ok)
		rec.TimeNs = timestampNs(extTS, opts.ClockRate)
		// A packet is late when its extended sequence precedes the high-water
		// mark already observed for this SSRC.
		rec.Reordered = ok && rec.ExtSequence < st.maxExt
		rec.Duplicate = st.seen.add(rec.ExtSequence)
		if rec.Duplicate {
			rec.Reordered = false
			st.stats.Duplicates++
		} else {
			st.stats.Unique++
			if rec.Reordered {
				st.stats.Reordered++
			}
			if st.stats.Unique == 1 {
				st.firstExt = rec.ExtSequence
				st.maxExt = rec.ExtSequence
			} else if rec.ExtSequence > st.maxExt {
				st.maxExt = rec.ExtSequence
			}
		}
		st.lastSeq = hdr.SequenceNumber
		st.lastExt = rec.ExtSequence
		st.lastTS = hdr.Timestamp
		st.extTS = extTS
		st.stats.Packets++
		if len(c.Records) < opts.MaxRecords {
			c.Records = append(c.Records, rec)
		} else {
			c.RecordsTruncated++
		}
		offset += int64(plen)
	}

	for _, st := range states {
		missing, gaps := st.seen.missing(st.firstExt, st.maxExt)
		st.stats.SSRC = st.ssrc
		st.stats.Missing = missing
		st.stats.GapRanges = gaps
		st.stats.Gaps = len(gaps)
		st.stats.FirstPacket = st.firstExt
		st.stats.LastPacket = st.maxExt
		c.Streams = append(c.Streams, st.stats)
	}
	sort.Slice(c.Streams, func(i, j int) bool { return c.Streams[i].SSRC < c.Streams[j].SSRC })
	model.SortErrors(c.Errors)
	return c, nil
}

// timestampNs converts an extended RTP timestamp at rate to nanoseconds,
// truncating toward zero. The 128-bit-safe path avoids overflow for long runs.
func timestampNs(ts uint64, rate uint32) int64 {
	if rate == 0 {
		return 0
	}
	sec := ts / uint64(rate)
	rem := ts % uint64(rate)
	const billion = uint64(1_000_000_000)
	if sec > uint64(1<<62)/billion {
		return int64(1<<63 - 1)
	}
	return int64(sec*billion + rem*billion/uint64(rate))
}

// String renders a range as "first-last".
func (r Range) String() string { return fmt.Sprintf("%d-%d", r.First, r.Last) }
